draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw a stick figure character
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 30, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 30, H/2 + 80);
  ctx.stroke();

  // Draw a fruit (apple) that moves up and down
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 + 120 + 20 * Math.sin(t), 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.stroke();

  // Draw a vegetable (carrot) that moves left and right
  ctx.fillStyle = 'orange';
  ctx.beginPath();
  ctx.arc(W/2 + 100 + 20 * Math.cos(t), H/2 + 180, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.stroke();

  ctx.restore();
}
